// Content with portions generated by generative AI platform
package org.eclipse.kura.core.configuration;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.mockito.Mockito.mock;

import java.util.Map;

import org.eclipse.kura.KuraException;
import org.eclipse.kura.core.configuration.metatype.Tad;
import org.eclipse.kura.core.configuration.metatype.Tocd;
import org.eclipse.kura.core.configuration.metatype.Toption;
import org.eclipse.kura.core.configuration.metatype.Tscalar;
import org.junit.Test;
import org.osgi.framework.Bundle;

public class InvalidMetatypeDefaultTest {

    private static final String PID = "ocd";
    private static final String ATTRIBUTE = "attribute";
    private static final String OTHER_ATTRIBUTE = "other";

    private final Tocd ocd = new Tocd();
    private Map<String, Object> defaults;

    @Test
    public void defaultOutsideTheRangeIsIgnored() throws KuraException {
        givenIntegerAttribute(ATTRIBUTE, "0");
        givenIntegerAttribute(OTHER_ATTRIBUTE, "5");

        whenDefaultsAreComputed();

        thenDefaultIsAbsent(ATTRIBUTE);
        thenDefaultIs(OTHER_ATTRIBUTE, 5);
    }

    @Test
    public void defaultOutsideTheOptionsIsIgnored() throws KuraException {
        givenStringAttributeWithOptions(ATTRIBUTE, "third", "first", "second");

        whenDefaultsAreComputed();

        thenDefaultIsAbsent(ATTRIBUTE);
    }

    @Test
    public void defaultAmongTheOptionsIsKept() throws KuraException {
        givenStringAttributeWithOptions(ATTRIBUTE, "second", "first", "second");

        whenDefaultsAreComputed();

        thenDefaultIs(ATTRIBUTE, "second");
    }

    @Test
    public void defaultComponentConfigurationOmitsInvalidDefaults() throws KuraException {
        givenIntegerAttribute(ATTRIBUTE, "0");
        givenIntegerAttribute(OTHER_ATTRIBUTE, "5");

        whenDefaultComponentConfigurationIsRequested();

        thenDefaultIsAbsent(ATTRIBUTE);
        thenDefaultIs(OTHER_ATTRIBUTE, 5);
    }

    @Test
    public void factoryComponentOcdOmitsInvalidDefaults() throws KuraException {
        givenIntegerAttribute(ATTRIBUTE, "0");
        givenIntegerAttribute(OTHER_ATTRIBUTE, "5");

        whenFactoryComponentOcdIsRequested();

        thenDefaultIsAbsent(ATTRIBUTE);
        thenDefaultIs(OTHER_ATTRIBUTE, 5);
    }

    private void givenIntegerAttribute(final String id, final String defaultValue) {
        final Tad attribute = attribute(id, Tscalar.INTEGER, defaultValue);
        attribute.setMin("1");
        attribute.setMax("10");
        this.ocd.addAD(attribute);
    }

    private void givenStringAttributeWithOptions(final String id, final String defaultValue, final String... options) {
        final Tad attribute = attribute(id, Tscalar.STRING, defaultValue);

        for (final String value : options) {
            final Toption option = new Toption();
            option.setLabel(value);
            option.setValue(value);
            attribute.setOption(option);
        }

        this.ocd.addAD(attribute);
    }

    private void whenDefaultsAreComputed() throws KuraException {
        this.ocd.setId(PID);
        this.defaults = new ConfigurationServiceImpl().getDefaultProperties(this.ocd);
    }

    private void whenDefaultComponentConfigurationIsRequested() throws KuraException {
        this.ocd.setId(PID);
        final ConfigurationServiceImpl service = new ConfigurationServiceImpl();
        service.registerComponentOCD(PID, this.ocd, true, mock(Bundle.class));
        this.defaults = service.getDefaultComponentConfiguration(PID).getConfigurationProperties();
    }

    private void whenFactoryComponentOcdIsRequested() throws KuraException {
        this.ocd.setId(PID);
        final ConfigurationServiceImpl service = new ConfigurationServiceImpl();
        service.registerComponentOCD(PID, this.ocd, true, mock(Bundle.class));
        this.defaults = service.getFactoryComponentOCD(PID).getConfigurationProperties();
    }

    private void thenDefaultIsAbsent(final String id) {
        assertFalse(this.defaults.containsKey(id));
    }

    private void thenDefaultIs(final String id, final Object value) {
        assertEquals(value, this.defaults.get(id));
    }

    private static Tad attribute(final String id, final Tscalar type, final String defaultValue) {
        final Tad attribute = new Tad();
        attribute.setId(id);
        attribute.setName(id);
        attribute.setType(type);
        attribute.setCardinality(0);
        attribute.setRequired(true);
        attribute.setDefault(defaultValue);
        return attribute;
    }
}
